//! Interaction sounds.
//! Plays short, soft UI sounds (bundled as resources/sounds/*.wav, generated by scripts/gen_sounds.py).
//! Playback is non-blocking: `play` is a channel send to a dedicated thread that owns the rodio output
//! stream. The stream is opened lazily on the first sound and closed again after ~10 min idle so we do not
//! hold the output device forever. WAVs are decoded once at `init`.

use once_cell::sync::Lazy;
use parking_lot::Mutex;
use rodio::buffer::SamplesBuffer;
use std::collections::HashMap;
use std::path::PathBuf;
use std::sync::mpsc::{self, RecvTimeoutError, Sender};
use std::sync::Arc;
use std::time::{Duration, Instant};

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Sound {
    /// Recording started.
    Start,
    /// Recording finished, processing.
    Stop,
    /// Cancelled.
    Cancel,
    /// Hands-free locked (double press).
    Lock,
    Error,
}

impl Sound {
    fn file_name(self) -> &'static str {
        match self {
            Sound::Start => "start.wav",
            Sound::Stop => "stop.wav",
            Sound::Cancel => "cancel.wav",
            Sound::Lock => "lock.wav",
            Sound::Error => "error.wav",
        }
    }
    const ALL: [Sound; 5] = [Sound::Start, Sound::Stop, Sound::Cancel, Sound::Lock, Sound::Error];
}

const IDLE_CLOSE: Duration = Duration::from_secs(600);

struct Clip {
    samples: Arc<Vec<f32>>,
    rate: u32,
}

type Bank = HashMap<Sound, Clip>;

enum Cmd {
    Load(Bank),
    Play(Sound),
}

static TX: Lazy<Mutex<Option<Sender<Cmd>>>> = Lazy::new(|| Mutex::new(None));

fn load_bank(dir: &PathBuf) -> Bank {
    let mut bank = Bank::new();
    for sound in Sound::ALL {
        let path = dir.join(sound.file_name());
        let decoded = std::fs::read(&path)
            .map_err(anyhow::Error::from)
            .and_then(|bytes| super::wav::decode_wav_mono_f32(&bytes));
        match decoded {
            Ok((samples, rate)) => {
                bank.insert(sound, Clip { samples: Arc::new(samples), rate });
            }
            Err(e) => log::warn!("sound {} not loaded from {}: {e}", sound.file_name(), path.display()),
        }
    }
    bank
}

/// Initialise with the directory containing the sound files (resolved by the core from Tauri resources).
pub fn init(sounds_dir: std::path::PathBuf) {
    let bank = load_bank(&sounds_dir);
    log::info!("loaded {} interaction sounds from {}", bank.len(), sounds_dir.display());
    let mut slot = TX.lock();
    if let Some(tx) = slot.as_ref() {
        let _ = tx.send(Cmd::Load(bank));
        return;
    }
    let (tx, rx) = mpsc::channel::<Cmd>();
    let _ = tx.send(Cmd::Load(bank));
    match std::thread::Builder::new().name("hoshiro-sounds".into()).spawn(move || player_thread(rx)) {
        Ok(_) => *slot = Some(tx),
        Err(e) => log::error!("cannot spawn sound thread: {e}"),
    }
}

pub fn play(sound: Sound) {
    if let Some(tx) = TX.lock().as_ref() {
        let _ = tx.send(Cmd::Play(sound));
    }
}

fn open_stream() -> Option<rodio::OutputStream> {
    match rodio::OutputStreamBuilder::open_default_stream() {
        Ok(mut s) => {
            s.log_on_drop(false);
            Some(s)
        }
        Err(e) => {
            log::warn!("cannot open audio output: {e}");
            None
        }
    }
}

fn player_thread(rx: mpsc::Receiver<Cmd>) {
    let mut bank = Bank::new();
    let mut stream: Option<rodio::OutputStream> = None;
    let mut last_used = Instant::now();
    loop {
        let cmd = if stream.is_some() {
            let remaining = IDLE_CLOSE.saturating_sub(last_used.elapsed());
            match rx.recv_timeout(remaining) {
                Ok(c) => c,
                Err(RecvTimeoutError::Timeout) => {
                    log::debug!("closing idle audio output");
                    stream = None;
                    continue;
                }
                Err(RecvTimeoutError::Disconnected) => return,
            }
        } else {
            match rx.recv() {
                Ok(c) => c,
                Err(_) => return,
            }
        };
        match cmd {
            Cmd::Load(b) => bank = b,
            Cmd::Play(sound) => {
                let Some(clip) = bank.get(&sound) else { continue };
                if stream.is_none() {
                    stream = open_stream();
                }
                if let Some(s) = stream.as_ref() {
                    s.mixer().add(SamplesBuffer::new(1, clip.rate, clip.samples.as_ref().clone()));
                    last_used = Instant::now();
                }
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn bundled_sounds_decode() {
        let dir = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("resources/sounds");
        let bank = load_bank(&dir);
        assert_eq!(bank.len(), 5);
        for (_, clip) in bank {
            assert_eq!(clip.rate, 44_100);
            assert!(clip.samples.len() > 3_000 && clip.samples.len() < 20_000);
            let peak = clip.samples.iter().fold(0.0f32, |a, b| a.max(b.abs()));
            assert!(peak > 0.05 && peak < 0.2, "peak {peak}");
        }
    }

    #[test]
    fn play_before_init_is_a_noop() {
        play(Sound::Start);
    }
}
